def verify():
    assert abs(1.5 / (0.4 / 0.6) - 2.25) < 1e-9 and math.ceil(10 / 0.7) == 15 and abs(math.log(99 * 99) / math.log(3) - 8.365) < 0.01
    A = 1.25; assert abs((A ** 4 - A) / (A ** 4 - 1) - 0.8266) < 0.001
    assert 0.5 ** 2 == 0.25 and abs(1 / 3 - 0.3333) < 1e-4 and 2 * 1 * 1 / 2 == 1 and 2 * (30 - 25) == 10 and 50 - 30 == 20


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
